from pathlib import Path

p = Path('app/classifieds/page.tsx')
text = p.read_text()

old = '  const [editingListing, setEditingListing] = useState<OfficeJobListing | null>(null);\n  const [manageError, setManageError] = useState("");'
new = '  const [editingListing, setEditingListing] = useState<OfficeJobListing | null>(null);\n  const [professionalManageListing, setProfessionalManageListing] = useState<OfficeJobListing | null>(null);\n  const [manageError, setManageError] = useState("");'
if old in text:
    text = text.replace(old, new, 1)

old_actions = '''<div className="grid w-full grid-cols-2 gap-2">\n          <button type="button" onClick={() => openEditProfessionalListing(job)} className="inline-flex items-center justify-center gap-1.5 rounded-xl border px-3 py-2 text-xs font-black shadow-sm transition hover:bg-white disabled:opacity-50" style={{ borderColor: theme.border, color: theme.text, backgroundColor: theme.pale }}><Pencil size={14}/> Edit</button>\n          {displayStatus === "paused" ? <button type="button" disabled={managingId === job.id} onClick={() => void manageProfessionalJob(job,"resume")} className="inline-flex items-center justify-center gap-1.5 rounded-xl border px-3 py-2 text-xs font-black shadow-sm transition hover:bg-white disabled:opacity-50" style={{ borderColor: theme.border, color: theme.text, backgroundColor: theme.pale }}><Play size={14}/> Resume</button> : isActive ? <button type="button" disabled={managingId === job.id} onClick={() => void manageProfessionalJob(job,"pause")} className="inline-flex items-center justify-center gap-1.5 rounded-xl border px-3 py-2 text-xs font-black shadow-sm transition hover:bg-white disabled:opacity-50" style={{ borderColor: theme.border, color: theme.text, backgroundColor: theme.pale }}><Pause size={14}/> Pause</button> : <span className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-center text-xs font-black text-slate-400">Paused</span>}\n          <button type="button" disabled={managingId === job.id} onClick={() => void manageProfessionalJob(job,"renew")} className="inline-flex items-center justify-center gap-1.5 rounded-xl px-3 py-2 text-xs font-black text-white shadow-sm transition hover:brightness-95 disabled:opacity-50" style={{ backgroundColor: theme.accent }}><RefreshCw size={14}/> Renew</button>\n          <button type="button" disabled={managingId === job.id} onClick={() => void manageProfessionalJob(job,"delete")} className="inline-flex items-center justify-center gap-1.5 rounded-xl border border-rose-200 bg-white px-3 py-2 text-xs font-black text-rose-600 shadow-sm transition hover:bg-rose-50 disabled:opacity-50"><Trash2 size={14}/> Delete</button>\n        </div>'''
new_actions = '''<div className="flex w-full justify-end">\n          <button type="button" onClick={() => setProfessionalManageListing(job)} className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#002757] px-4 py-2.5 text-xs font-black text-white shadow-md transition hover:bg-[#01A32E]"><MoreVertical size={15}/> Manage</button>\n        </div>'''
if old_actions not in text:
    raise SystemExit('professional action block not found')
text = text.replace(old_actions, new_actions, 1)

anchor = '        {portalRole && <section className="h-full min-h-[250px] min-w-0 rounded-2xl border border-[#002757]/15 bg-white p-4 shadow-sm sm:p-5">'
if anchor not in text:
    raise SystemExit('connections anchor not found')

modal = '''        {professionalManageListing && (() => {\n          const job = professionalManageListing;\n          const daysLeft = Math.max(0, Math.ceil((new Date(job.expires_at).getTime() - Date.now()) / 86400000));\n          const isActive = job.status === "active" && daysLeft > 0;\n          const displayStatus = job.status === "active" && daysLeft === 0 ? "expired" : job.status;\n          const theme = getProfessionalCardTheme(job.profession);\n          return <div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#001a38]/55 p-4" onMouseDown={(e) => { if (e.target === e.currentTarget) setProfessionalManageListing(null); }}>\n            <div className="w-full max-w-sm overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-2xl">\n              <div className="flex items-start justify-between gap-4 border-b border-slate-100 p-5">\n                <div><p className="text-xs font-black uppercase tracking-[0.12em]" style={{ color: theme.text }}>Manage</p><h3 className="mt-1 text-lg font-black text-[#002757]">{job.profession}</h3><p className="mt-1 text-sm font-semibold text-slate-500">{job.city}, {job.province}</p></div>\n                <button type="button" onClick={() => setProfessionalManageListing(null)} className="grid h-10 w-10 shrink-0 place-items-center rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50"><X size={18}/></button>\n              </div>\n              <div className="grid grid-cols-2 gap-3 p-5">\n                <button type="button" onClick={() => { setProfessionalManageListing(null); openEditProfessionalListing(job); }} className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-black text-[#002757] hover:bg-[#edf3fa]"><Pencil size={16}/> Edit</button>\n                {displayStatus === "paused" ? <button type="button" disabled={managingId === job.id} onClick={async () => { await manageProfessionalJob(job, "resume"); setProfessionalManageListing(null); }} className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-black text-[#002757] hover:bg-[#edf3fa] disabled:opacity-50"><Play size={16}/> Resume</button> : <button type="button" disabled={!isActive || managingId === job.id} onClick={async () => { await manageProfessionalJob(job, "pause"); setProfessionalManageListing(null); }} className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-black text-[#002757] hover:bg-[#edf3fa] disabled:opacity-50"><Pause size={16}/> Pause</button>}\n                <button type="button" disabled={managingId === job.id} onClick={async () => { await manageProfessionalJob(job, "renew"); setProfessionalManageListing(null); }} className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#01A32E] px-4 py-3 text-sm font-black text-white hover:bg-[#018a28] disabled:opacity-50"><RefreshCw size={16}/> Renew</button>\n                <button type="button" disabled={managingId === job.id} onClick={async () => { await manageProfessionalJob(job, "delete"); setProfessionalManageListing(null); }} className="inline-flex items-center justify-center gap-2 rounded-xl border border-rose-200 bg-white px-4 py-3 text-sm font-black text-rose-600 hover:bg-rose-50 disabled:opacity-50"><Trash2 size={16}/> Delete</button>\n              </div>\n            </div>\n          </div>;\n        })()}\n\n'''
text = text.replace(anchor, modal + anchor, 1)
p.write_text(text)
print('Added simplified Manage modal for professional postings')
